// SupportedArchitectures returns the GPU architectures recorded for the given toolkit version.
func SupportedArchitectures(v Version) []string {
	if archs, ok := staticSupportedArchitectures[v]; ok {
		return append([]string(nil), archs...)
	}
	var best Version
	for known := range staticSupportedArchitectures {
		if known.Compare(v) <= 0 && known.Compare(best) > 0 {
			best = known
		}
	}
	if best.Valid() {
		return append([]string(nil), staticSupportedArchitectures[best]...)
	}
	return nil
}
